INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass KVP immer große Änderungen erfordert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kleine Schritte sind typisch"}, {"text": "Ja", "correct": false, "because": "KVP fokussiert Inkrementelles"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich KVP in einem IT-Projekt einführe?', 3, '[{"text": "Mitarbeiterbeteiligung", "correct": true, "because": "Fördert Ideen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Neue Hardware", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu einem KVP in der IT?', 5, '[{"text": "Problemidentifikation", "correct": true, "because": "Startpunkt der Verbesserung"}, {"text": "Maßnahmenplanung", "correct": true, "because": "Strukturiert Lösung"}, {"text": "Große Investitionen", "correct": false, "because": "Nicht zwingend"}, {"text": "Einmalige Änderung", "correct": false, "because": "KVP ist kontinuierlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) KVP fördert Effizienz. b) Es braucht immer externe Berater.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Intern umsetzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich KVP für ein IT-System anwende?', 4, '[{"text": "Teamvorschläge", "correct": false, "because": "Kern von KVP"}, {"text": "Prozessanalyse", "correct": false, "because": "Identifiziert Schwächen"}, {"text": "Bürodeko", "correct": true, "because": "Kein Prozessfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob KVP nur für große Firmen geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMU nützlich"}, {"text": "Ja", "correct": false, "because": "Skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit KVP in der IT?', 3, '[{"text": "Prozessoptimierung", "correct": true, "because": "Steigert Effizienz"}, {"text": "Einmalige Lösung", "correct": false, "because": "KVP ist kontinuierlich"}, {"text": "Weniger Teamarbeit", "correct": false, "because": "Fördert Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen KVP in der IT?', 5, '[{"text": "Feedbackschleifen", "correct": true, "because": "Liefert Verbesserungsideen"}, {"text": "PDCA-Zyklus", "correct": true, "because": "Strukturiert Prozess"}, {"text": "Große Umstrukturierung", "correct": false, "because": "Nicht inkrementell"}, {"text": "Einmalige Prüfung", "correct": false, "because": "KVP ist fortlaufend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) KVP reduziert Fehler. b) Es ist einmalig abgeschlossen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "KVP ist kontinuierlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für KVP in einem IT-Team?', 4, '[{"text": "Ideensammlung", "correct": false, "because": "Kern von KVP"}, {"text": "Regelmäßige Reviews", "correct": false, "because": "Überprüft Fortschritt"}, {"text": "Luxusausstattung", "correct": true, "because": "Kein Prozessfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist KVP in der IT immer teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Kleine Maßnahmen oft günstig"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet KVP für IT-Prozesse?', 4, '[{"text": "Höhere Effizienz", "correct": true, "because": "Optimiert Abläufe"}, {"text": "Fehlerreduktion", "correct": true, "because": "Verbessert Qualität"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass KVP nur für Produktion geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in IT anwendbar"}, {"text": "Ja", "correct": false, "because": "Nicht branchenspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um KVP in einem IT-Support-Team umzusetzen?', 3, '[{"text": "Regelmäßige Meetings", "correct": true, "because": "Fördert Ideen"}, {"text": "Teure Tools", "correct": false, "because": "Nicht zwingend"}, {"text": "Einmalige Schulung", "correct": false, "because": "KVP ist fortlaufend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) KVP nutzt Teamwissen. b) Es erfordert immer neue Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern KVP in der IT?', 5, '[{"text": "Offene Kommunikation", "correct": true, "because": "Ermöglicht Ideen"}, {"text": "Kontinuierliche Überprüfung", "correct": true, "because": "Sichert Fortschritt"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht erforderlich"}, {"text": "Einmalige Maßnahmen", "correct": false, "because": "KVP ist fortlaufend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich KVP in einem IT-Projekt starte?', 3, '[{"text": "Mitarbeiterinput", "correct": false, "because": "Kern von KVP"}, {"text": "Prozessdokumentation", "correct": false, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Prozessfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordert KVP in der IT immer große Teams?', 3, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams effektiv"}, {"text": "Ja", "correct": false, "because": "Größe nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob KVP in der IT die Qualität steigert?', 2, '[{"text": "Ja", "correct": true, "because": "Reduziert Fehler"}, {"text": "Nein", "correct": false, "because": "Qualität ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für KVP in der IT?', 4, '[{"text": "Kontinuierliche Anpassung", "correct": true, "because": "Definiert KVP"}, {"text": "Einmalige Lösung", "correct": false, "because": "Nicht fortlaufend"}, {"text": "Neue Geräte", "correct": false, "because": "Nicht primär"}]');
